competency_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX fhir: <http://hl7.org/fhir/>
PREFIX fasto: <https://bioportal.bioontology.org/ontologies/FASTO/>
PREFIX ftdm: <https://bioportal.bioontology.org/ontologies/FTDM/>
PREFIX ftdmowl: <https://bioportal.bioontology.org/ontologies/FTDM.owl#>
PREFIX ddo: <http://purl.obolibrary.org/obo/DDO.owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ontofood: <http://www.owl-ontologies.com/OntoFood.owl#>
SELECT ?meal ?carbs ?fat ?protein ?carbInsulin ?correction ?exerciseInsulin WHERE {
  OPTIONAL { ?meal ftdmowl:DMTO_0002116 ?carbs . }
  OPTIONAL { ?meal ftdmowl:DMTO_0002156 ?fat . }
  OPTIONAL { ?meal ftdmowl:DMTO_0002157 ?protein . }
  OPTIONAL { ?meal fasto:Meal.insulinUnitsForCarbs ?carbInsulin . }
  OPTIONAL { ?meal fasto:Meal.correctionInsulinUnits ?correction . }
  OPTIONAL { ?meal fasto:Meal.insulinUnitsForExercise ?exerciseInsulin . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX fhir: <http://hl7.org/fhir/>
PREFIX fasto: <https://bioportal.bioontology.org/ontologies/FASTO/>
PREFIX ftdm: <https://bioportal.bioontology.org/ontologies/FTDM/>
PREFIX ftdmowl: <https://bioportal.bioontology.org/ontologies/FTDM.owl#>
PREFIX ddo: <http://purl.obolibrary.org/obo/DDO.owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ontofood: <http://www.owl-ontologies.com/OntoFood.owl#>
SELECT ?meal ?fiber ?carbs WHERE {
  OPTIONAL { ?meal ftdmowl:DMTO_0002117 ?fiber . }
  OPTIONAL { ?meal ftdmowl:DMTO_0002116 ?carbs . }
  OPTIONAL { ?meal fasto:Meal.totalCarbsInGrams ?carbsTotal . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX fhir: <http://hl7.org/fhir/>
PREFIX fasto: <https://bioportal.bioontology.org/ontologies/FASTO/>
PREFIX ftdm: <https://bioportal.bioontology.org/ontologies/FTDM/>
PREFIX ftdmowl: <https://bioportal.bioontology.org/ontologies/FTDM.owl#>
PREFIX ddo: <http://purl.obolibrary.org/obo/DDO.owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ontofood: <http://www.owl-ontologies.com/OntoFood.owl#>
SELECT ?patient ?carePlan WHERE {
  { ?patient a ftdmowl:child . } UNION { ?patient a ftdmowl:adult . }
  OPTIONAL { ?carePlan a ftdmowl:DMTO_0000044 . }
}
